// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IERC1155AsteroidX.sol";
import "./marketplace/interfaces/IAsteroidXMarketplace.sol";
import "./AsteroidXMarketplaceVault.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import "@openzeppelin/contracts/token/ERC1155/utils/ERC1155Holder.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC1155/utils/ERC1155HolderUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

contract AsteroidXMarketplace is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ERC1155HolderUpgradeable,
    ReentrancyGuardUpgradeable,
    AsteroidXMarketplaceErrors,
    IAsteroidXMarketplace
{
    // Constants with maximum allowed values
    uint256 public constant MAX_PRICE_PER_TOKEN = 1000000 ether;
    uint256 public constant MAX_AMOUNT_PER_LISTING = 1000000;
    uint256 public constant MAX_FEE_PERCENTAGE = 2000; // 20%
    uint256 public constant MIN_TIMELOCK_DURATION = 1 days;
    uint256 public constant MAX_TIMELOCK_DURATION = 30 days;

    uint256 public timelockDuration;

    using AsteroidXMarketplaceStructs for AsteroidXMarketplaceStructs.Listing;
    using AsteroidXMarketplaceStructs for AsteroidXMarketplaceStructs.Offer;
    using AsteroidXMarketplaceStructs for AsteroidXMarketplaceStructs.Activity;
    using AsteroidXMarketplaceStructs for AsteroidXMarketplaceStructs.PriceRecord;

    using EnumerableSet for EnumerableSet.UintSet;
    using EnumerableSet for EnumerableSet.AddressSet;
    using SafeERC20 for IERC20;

    uint256 public platformFeePercentage;
    address public feeRecipient;
    IERC1155AsteroidX public asteroidXToken;
    AsteroidXMarketplaceVault public marketplaceVaultContract;

    mapping(uint256 => AsteroidXMarketplaceStructs.Listing) public listings;
    uint256 private _nextListingId;
    mapping(uint256 => AsteroidXMarketplaceStructs.Activity[])
        public tokenActivities;
    AsteroidXMarketplaceStructs.PendingUpdate public pendingFeeUpdate;
    AsteroidXMarketplaceStructs.PendingUpdate public pendingRecipientUpdate;

    mapping(uint256 => EnumerableSet.UintSet) private activeListingsByToken;
    mapping(address => EnumerableSet.UintSet) private activeListingsBySeller;
    mapping(uint256 => EnumerableSet.UintSet) private activeOffersByToken;
    mapping(address => EnumerableSet.UintSet) private activeOffersByBuyer;

    uint256 private _nextOfferId;
    mapping(uint256 => AsteroidXMarketplaceStructs.Offer) public offers;
    mapping(bytes4 => bool) public functionPaused;

    AsteroidXMarketplaceStructs.PriceRecord[] private priceHistories;
    mapping(uint256 => uint256[]) private tokenPriceHistoryIndexes;

    EnumerableSet.AddressSet private _supportedPaymentTokensSet;
    mapping(address => uint256) public paymentTokenFeeRates;

    uint256[49] private __gap;

    modifier withVaultCheck() {
        _checkVaultAvailable();
        _;
    }

    function _checkVaultAvailable() internal view {
        if (address(marketplaceVaultContract) == address(0))
            revert VaultNotSet();
        if (marketplaceVaultContract.paused()) revert VaultIsPaused();
    }

    /**
     * @notice Initializes the marketplace contract.
     * @param _tokenAddress The address of the ERC1155 token contract.
     * @param _feeRecipient The address that will receive platform fees.
     * @param _platformFeePercentage The initial platform fee percentage in basis points.
     * @param _marketplaceVaultAddress The address of the marketplace vault contract.
     */
    function initialize(
        address _tokenAddress,
        address _feeRecipient,
        uint256 _platformFeePercentage,
        address _marketplaceVaultAddress
    ) public initializer {
        if (_tokenAddress == address(0))
            revert InvalidTokenAddress(_tokenAddress);
        if (_feeRecipient == address(0)) revert InvalidRecipient();
        if (_platformFeePercentage > MAX_FEE_PERCENTAGE)
            revert InvalidFeePercentage(
                _platformFeePercentage,
                MAX_FEE_PERCENTAGE
            );
        if (_marketplaceVaultAddress == address(0))
            revert InvalidMarketplaceVaultAddress(_marketplaceVaultAddress);

        __ERC1155Holder_init();
        __Ownable_init(msg.sender);
        __Pausable_init();
        __ReentrancyGuard_init();

        asteroidXToken = IERC1155AsteroidX(_tokenAddress);
        feeRecipient = _feeRecipient;
        platformFeePercentage = _platformFeePercentage;
        marketplaceVaultContract = AsteroidXMarketplaceVault(
            payable(_marketplaceVaultAddress)
        );
        timelockDuration = 2 days;
        _nextListingId = 1;
        _nextOfferId = 1;

        _supportedPaymentTokensSet.add(address(0));
        paymentTokenFeeRates[address(0)] = _platformFeePercentage;
        emit PaymentTokenConfigUpdated(
            address(0),
            true,
            _platformFeePercentage
        );
    }

    /**
     * @notice Updates the timelock duration for sensitive operations.
     * @dev Can only be called by the owner. Duration must be within MIN_TIMELOCK_DURATION and MAX_TIMELOCK_DURATION.
     * @param newDuration The new timelock duration in seconds.
     */
    function updateTimelockDuration(uint256 newDuration) external onlyOwner {
        if (
            newDuration < MIN_TIMELOCK_DURATION ||
            newDuration > MAX_TIMELOCK_DURATION
        ) {
            revert InvalidTimelockDuration(
                newDuration,
                MIN_TIMELOCK_DURATION,
                MAX_TIMELOCK_DURATION
            );
        }
        uint256 oldDuration = timelockDuration;
        timelockDuration = newDuration;
        emit TimelockDurationUpdated(oldDuration, newDuration);
    }

    /**
     * @notice Creates a new listing for selling ERC1155 tokens.
     * @dev Tokens are transferred to the marketplace vault upon listing creation.
     * @param tokenId The ID of the token to list.
     * @param amount The amount of tokens to list.
     * @param pricePerToken The price per token in wei (or smallest unit of ERC20).
     * @param expirationTime The Unix timestamp when the listing expires.
     * @param paymentToken The address of the ERC20 token for payment, or address(0) for native currency.
     */
    function createListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) external nonReentrant whenNotPaused whenFunctionNotPaused withVaultCheck {
        _validateListing(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        _transferNFT(
            msg.sender,
            address(marketplaceVaultContract),
            tokenId,
            amount,
            false
        );
        uint256 listingId = _nextListingId++;
        listings[listingId] = AsteroidXMarketplaceStructs.Listing({
            listingId: listingId,
            seller: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeListingsByToken[tokenId].add(listingId);
        activeListingsBySeller[msg.sender].add(listingId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.LISTING,
            msg.sender,
            address(0),
            amount,
            pricePerToken,
            paymentToken,
            listingId
        );
        emit ListingCreated(
            listingId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

    /**
     * @notice Cancels an active listing.
     * @dev Only the seller of the listing can cancel it. NFTs are returned to the seller from the vault.
     * @param listingId The ID of the listing to cancel.
     */
    function cancelListing(uint256 listingId)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) revert ListingNotActive(listingId);
        if (listing.seller != msg.sender)
            revert NotSeller(listingId, msg.sender);
        _deactivateListing(listingId);
        marketplaceVaultContract.returnNFTToSeller(
            address(asteroidXToken),
            listing.tokenId,
            listing.amount,
            listing.seller
        );
        _recordTransaction(
            listing.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING,
            msg.sender,
            address(0),
            listing.amount,
            0,
            listing.paymentToken,
            listingId
        );
        emit ListingCancelled(listingId);
    }

    /**
     * @notice Purchases a specified amount of tokens from an active listing.
     * @dev Handles payment in native currency (msg.value) or ERC20 tokens.
     * @param listingId The ID of the listing to purchase from.
     * @param amount The amount of tokens to purchase.
     */
    function purchaseListing(uint256 listingId, uint256 amount)
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) revert ListingNotActive(listingId);
        if (block.timestamp >= listing.expirationTime)
            revert ListingExpired(listingId, listing.expirationTime);
        if (amount == 0 || amount > listing.amount)
            revert InvalidAmount(amount, listing.amount);
        if (msg.sender == listing.seller) revert CannotBuyOwnListing();

        uint256 totalPrice = amount * listing.pricePerToken;
        listing.amount -= amount;
        if (listing.amount == 0) {
            _deactivateListing(listingId);
        }
        marketplaceVaultContract.transferNFTToBuyer(
            address(asteroidXToken),
            listing.tokenId,
            amount,
            msg.sender
        );
        _handlePaymentWithFees(
            listing.paymentToken,
            msg.sender,
            listing.seller,
            totalPrice,
            msg.value,
            listing.paymentToken
        );
        _recordTransaction(
            listing.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.SALE,
            listing.seller,
            msg.sender,
            amount,
            listing.pricePerToken,
            listing.paymentToken,
            listingId
        );
        emit ListingSold(
            listingId,
            msg.sender,
            listing.tokenId,
            amount,
            totalPrice,
            block.timestamp,
            listing.paymentToken
        );
    }

    /**
     * @notice Creates an offer to buy a specified amount of tokens.
     * @dev Funds (native or ERC20) are transferred to this contract and then deposited into the vault.
     * @param tokenId The ID of the token for which the offer is made.
     * @param amount The amount of tokens to offer to buy.
     * @param pricePerToken The price per token offered.
     * @param expirationTime The Unix timestamp when the offer expires.
     * @param paymentToken The address of the ERC20 token for payment, or address(0) for native currency.
     */
    function makeOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    )
        external
        payable
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        _validateOffer(
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            paymentToken
        );
        uint256 totalOfferValue = amount * pricePerToken;
        uint256 offerId = _nextOfferId++;
        _handlePayment(
            paymentToken,
            msg.sender,
            address(this),
            totalOfferValue,
            msg.value
        );
        if (paymentToken == address(0)) {
            marketplaceVaultContract.depositOfferFunds{value: totalOfferValue}(
                offerId
            );
        } else {
            IERC20 token = IERC20(paymentToken);
            token.approve(address(marketplaceVaultContract), totalOfferValue);
            marketplaceVaultContract.depositOfferERC20Funds(
                offerId,
                paymentToken,
                totalOfferValue,
                address(this)
            );
        }
        offers[offerId] = AsteroidXMarketplaceStructs.Offer({
            offerId: offerId,
            buyer: msg.sender,
            tokenId: tokenId,
            amount: amount,
            pricePerToken: pricePerToken,
            expirationTime: expirationTime,
            active: true,
            timestamp: block.timestamp,
            paymentToken: paymentToken
        });
        activeOffersByToken[tokenId].add(offerId);
        activeOffersByBuyer[msg.sender].add(offerId);
        _recordTransaction(
            tokenId,
            AsteroidXMarketplaceStructs.ActivityType.MAKE_OFFER,
            msg.sender,
            address(marketplaceVaultContract),
            amount,
            pricePerToken,
            paymentToken,
            offerId
        );
        emit OfferCreated(
            offerId,
            msg.sender,
            tokenId,
            amount,
            pricePerToken,
            expirationTime,
            block.timestamp,
            paymentToken
        );
    }

    /**
     * @notice Cancels an active offer made by the caller.
     * @dev Escrowed funds are returned to the offer maker (buyer) from the vault.
     * @param offerId The ID of the offer to cancel.
     */
    function cancelOffer(uint256 offerId)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer != msg.sender) revert NotBuyer(offerId, msg.sender);
        _deactivateOffer(offerId);
        uint256 refundAmount = offer.amount * offer.pricePerToken;
        _handleOfferFundRefund(
            offerId,
            offer.paymentToken,
            msg.sender,
            refundAmount
        );
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.CANCEL_OFFER,
            address(marketplaceVaultContract),
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferCancelled(offerId);
    }

    /**
     * @notice Accepts an active offer for tokens owned by the caller.
     * @dev NFTs are transferred from the seller (caller) to the buyer (offer maker) via the vault.
     * Funds are transferred from the vault to the seller and fee recipient.
     * @param offerId The ID of the offer to accept.
     */
    function acceptOffer(uint256 offerId)
        external
        nonReentrant
        whenNotPaused
        whenFunctionNotPaused
        withVaultCheck
    {
        AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];
        if (!offer.active) revert OfferNotActive(offerId);
        if (offer.buyer == msg.sender) revert CannotAcceptOwnOffer();
        if (block.timestamp >= offer.expirationTime)
            revert OfferExpired(offerId, offer.expirationTime);

        IERC1155AsteroidX token = asteroidXToken;
        if (token.balanceOf(msg.sender, offer.tokenId) < offer.amount)
            revert InsufficientTokenBalance(offer.tokenId, offer.amount);

        uint256 totalOfferValue = offer.amount * offer.pricePerToken;
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalOfferValue,
            offer.paymentToken
        );

        _transferNFT(
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            true
        );
        _handleOfferFundWithdrawal(
            offerId,
            offer.paymentToken,
            msg.sender,
            feeRecipient,
            sellerProceeds,
            platformFee
        );
        _deactivateOffer(offerId);
        _recordTransaction(
            offer.tokenId,
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER,
            msg.sender,
            offer.buyer,
            offer.amount,
            offer.pricePerToken,
            offer.paymentToken,
            offerId
        );
        emit OfferAccepted(
            offerId,
            msg.sender,
            offer.buyer,
            offer.tokenId,
            offer.amount,
            totalOfferValue,
            block.timestamp,
            offer.paymentToken
        );
    }

    /**
     * @dev Records an activity related to token transactions or marketplace actions.
     * Internal function called by other functions like createListing, purchaseListing, etc.
     */
    function _recordActivity(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken
    ) internal {
        tokenActivities[tokenId].push(
            AsteroidXMarketplaceStructs.Activity({
                activityType: activityType,
                from: from,
                to: to,
                tokenId: tokenId,
                amount: amount,
                price: price,
                timestamp: block.timestamp,
                paymentToken: paymentToken
            })
        );
    }

    /**
     * @dev Calculates the start index and page length for pagination.
     * @param totalItems The total number of items to paginate over.
     * @param offset The number of items to skip from the beginning (0-indexed).
     * @param limit The maximum number of items to return for the page.
     * @return startIdx The calculated starting index in a 0-indexed array (considering newest first).
     * @return pageLength The number of items to include in the current page.
     */
    function _getPaginationRange(
        uint256 totalItems,
        uint256 offset,
        uint256 limit
    ) internal pure returns (uint256 startIdx, uint256 pageLength) {
        if (offset >= totalItems) {
            return (0, 0);
        }
        uint256 itemsLeft = totalItems - offset;
        pageLength = Math.min(limit, itemsLeft);
        startIdx = totalItems - offset - pageLength;
        return (startIdx, pageLength);
    }

    /**
     * @dev Internal helper to fetch and filter listings for pagination.
     * @param idSet The EnumerableSet of listing IDs to process.
     * @param offset Pagination offset.
     * @param limit Pagination limit.
     * @param filterByUser Address of the user to filter by (e.g., seller). address(0) for no user filter.
     * @param filterByTokenId Token ID to filter by (0 for no token filter).
     * @param userMustMatch If true, userAddress must match listing.seller. If false and userAddress is set, listing.seller must NOT match.
     * @return items Array of Listing structs for the current page.
     * @return totalValid Total number of listings matching all filters.
     */
    function _getPaginatedListingsInternal(
        EnumerableSet.UintSet storage idSet,
        uint256 offset,
        uint256 limit,
        address filterByUser,
        uint256 filterByTokenId,
        bool userMustMatch
    )
        internal
        view
        returns (
            AsteroidXMarketplaceStructs.Listing[] memory items,
            uint256 totalValid
        )
    {
        uint256 totalInSet = idSet.length();
        AsteroidXMarketplaceStructs.Listing[]
            memory tempListings = new AsteroidXMarketplaceStructs.Listing[](
                totalInSet
            );
        uint256 validCount = 0;

        for (uint256 i = 0; i < totalInSet; i++) {
            uint256 listingId = idSet.at(i);
            AsteroidXMarketplaceStructs.Listing
                storage currentListing = listings[listingId];

            bool userConditionMet = (filterByUser == address(0)) ||
                (userMustMatch && currentListing.seller == filterByUser) ||
                (!userMustMatch && currentListing.seller != filterByUser);

            bool tokenConditionMet = (filterByTokenId == 0) ||
                (currentListing.tokenId == filterByTokenId);

            if (
                userConditionMet &&
                tokenConditionMet &&
                currentListing.active &&
                block.timestamp < currentListing.expirationTime
            ) {
                if (validCount < totalInSet) {
                    tempListings[validCount] = currentListing;
                }
                validCount++;
            }
        }
        totalValid = validCount;

        (uint256 startIdx, uint256 pageLength) = _getPaginationRange(
            totalValid,
            offset,
            limit
        );

        if (pageLength == 0) {
            return (new AsteroidXMarketplaceStructs.Listing[](0), totalValid);
        }
        items = new AsteroidXMarketplaceStructs.Listing[](pageLength);
        for (uint256 i = 0; i < pageLength; i++) {
            items[i] = tempListings[startIdx + i];
        }
        return (items, totalValid);
    }

    /**
     * @dev Internal helper to fetch and filter offers for pagination.
     * @param idSet The EnumerableSet of offer IDs to process.
     * @param offset Pagination offset.
     * @param limit Pagination limit.
     * @param filterByUser Address of the user to filter by (e.g., buyer). address(0) for no user filter.
     * @param filterByTokenId Token ID to filter by (0 for no token filter).
     * @param userMustMatch If true, userAddress must match offer.buyer. If false and userAddress is set, offer.buyer must NOT match.
     * @return items Array of Offer structs for the current page.
     * @return totalValid Total number of offers matching all filters.
     */
    function _getPaginatedOffersInternal(
        EnumerableSet.UintSet storage idSet,
        uint256 offset,
        uint256 limit,
        address filterByUser,
        uint256 filterByTokenId,
        bool userMustMatch
    )
        internal
        view
        returns (
            AsteroidXMarketplaceStructs.Offer[] memory items,
            uint256 totalValid
        )
    {
        uint256 totalInSet = idSet.length();
        AsteroidXMarketplaceStructs.Offer[]
            memory tempOffers = new AsteroidXMarketplaceStructs.Offer[](
                totalInSet
            );
        uint256 validCount = 0;

        for (uint256 i = 0; i < totalInSet; i++) {
            uint256 offerId = idSet.at(i);
            AsteroidXMarketplaceStructs.Offer storage currentOffer = offers[
                offerId
            ];

            bool userConditionMet = (filterByUser == address(0)) ||
                (userMustMatch && currentOffer.buyer == filterByUser) ||
                (!userMustMatch && currentOffer.buyer != filterByUser);

            bool tokenConditionMet = (filterByTokenId == 0) ||
                (currentOffer.tokenId == filterByTokenId);

            if (
                userConditionMet &&
                tokenConditionMet &&
                currentOffer.active &&
                block.timestamp < currentOffer.expirationTime
            ) {
                if (validCount < totalInSet) {
                    tempOffers[validCount] = currentOffer;
                }
                validCount++;
            }
        }
        totalValid = validCount;

        (uint256 startIdx, uint256 pageLength) = _getPaginationRange(
            totalValid,
            offset,
            limit
        );

        if (pageLength == 0) {
            return (new AsteroidXMarketplaceStructs.Offer[](0), totalValid);
        }
        items = new AsteroidXMarketplaceStructs.Offer[](pageLength);
        for (uint256 i = 0; i < pageLength; i++) {
            items[i] = tempOffers[startIdx + i];
        }
        return (items, totalValid);
    }

    /**
     * @dev Internal helper to fetch and filter offers for pagination (including expired but not cancelled).
     * @param idSet The EnumerableSet of offer IDs to process.
     * @param offset Pagination offset.
     * @param limit Pagination limit.
     * @param filterByUser Address of the user to filter by (e.g., buyer). address(0) for no user filter.
     * @param filterByTokenId Token ID to filter by (0 for no token filter).
     * @param userMustMatch If true, userAddress must match offer.buyer. If false and userAddress is set, offer.buyer must NOT match.
     * @return items Array of Offer structs for the current page.
     * @return totalValid Total number of offers matching all filters.
     */
    function _getPaginatedOffersInternalIncludingExpired(
        EnumerableSet.UintSet storage idSet,
        uint256 offset,
        uint256 limit,
        address filterByUser,
        uint256 filterByTokenId,
        bool userMustMatch
    )
        internal
        view
        returns (
            AsteroidXMarketplaceStructs.Offer[] memory items,
            uint256 totalValid
        )
    {
        uint256 totalInSet = idSet.length();
        AsteroidXMarketplaceStructs.Offer[]
            memory tempOffers = new AsteroidXMarketplaceStructs.Offer[](
                totalInSet
            );
        uint256 validCount = 0;

        for (uint256 i = 0; i < totalInSet; i++) {
            uint256 offerId = idSet.at(i);
            AsteroidXMarketplaceStructs.Offer storage currentOffer = offers[
                offerId
            ];

            bool userConditionMet = (filterByUser == address(0)) ||
                (userMustMatch && currentOffer.buyer == filterByUser) ||
                (!userMustMatch && currentOffer.buyer != filterByUser);

            bool tokenConditionMet = (filterByTokenId == 0) ||
                (currentOffer.tokenId == filterByTokenId);

            if (
                userConditionMet && tokenConditionMet && currentOffer.active // Only check active status, not expiration time
            ) {
                if (validCount < totalInSet) {
                    tempOffers[validCount] = currentOffer;
                }
                validCount++;
            }
        }
        totalValid = validCount;

        (uint256 startIdx, uint256 pageLength) = _getPaginationRange(
            totalValid,
            offset,
            limit
        );

        if (pageLength == 0) {
            return (new AsteroidXMarketplaceStructs.Offer[](0), totalValid);
        }
        items = new AsteroidXMarketplaceStructs.Offer[](pageLength);
        for (uint256 i = 0; i < pageLength; i++) {
            items[i] = tempOffers[startIdx + i];
        }
        return (items, totalValid);
    }

    /**
     * @notice Gets active listings for a specific seller, paginated.
     * @dev Filters out expired or inactive listings.
     * @param seller The address of the seller.
     * @param offset The offset for pagination.
     * @param limit The limit for pagination.
     * @return items An array of Listing structs.
     * @return total The total number of active listings for the seller.
     */
    function getActiveListingsBySellerPaginated(
        address seller,
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (
            AsteroidXMarketplaceStructs.Listing[] memory items,
            uint256 total
        )
