    /**
     * @notice Gets all active (non-expired, active=true) listings for a specific token.
     * @param tokenId The ID of the token.
     * @return An array of all active Listing structs for the token.
     */
    function getAllActiveListingsForToken(uint256 tokenId)
        external
        view
        returns (AsteroidXMarketplaceStructs.Listing[] memory)
    {
        EnumerableSet.UintSet storage listingIdsSet = activeListingsByToken[
            tokenId
        ];
        uint256 totalInSet = listingIdsSet.length();
        AsteroidXMarketplaceStructs.Listing[]
            memory tempListings = new AsteroidXMarketplaceStructs.Listing[](
                totalInSet
            );
        uint256 validCount = 0;
        for (uint256 i = 0; i < totalInSet; i++) {
            uint256 listingId = listingIdsSet.at(i);
            AsteroidXMarketplaceStructs.Listing
                storage currentListing = listings[listingId];
            if (
                currentListing.active &&
                block.timestamp < currentListing.expirationTime
            ) {
                tempListings[validCount] = currentListing;
                validCount++;
            }
        }
        AsteroidXMarketplaceStructs.Listing[]
            memory validListings = new AsteroidXMarketplaceStructs.Listing[](
                validCount
            );
        for (uint256 i = 0; i < validCount; i++) {
            validListings[i] = tempListings[i];
        }
        return validListings;
    }

    /**
     * @notice Gets the price history for a specific token, paginated.
     * @param tokenId The ID of the token.
     * @param offset The offset for pagination.
     * @param limit The limit for pagination.
     * @return items An array of PriceRecord structs.
     * @return total The total number of price history records for the token.
     */
    function getPriceHistoryPaginated(
        uint256 tokenId,
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (
            AsteroidXMarketplaceStructs.PriceRecord[] memory items,
            uint256 total
        )
    {
        uint256[] storage indexes = tokenPriceHistoryIndexes[tokenId];
        total = indexes.length;
        (uint256 start, uint256 length) = _getPaginationRange(
            total,
            offset,
            limit
        );
        if (length == 0) {
            return (new AsteroidXMarketplaceStructs.PriceRecord[](0), total);
        }
        items = new AsteroidXMarketplaceStructs.PriceRecord[](length);
        for (uint256 i = 0; i < length; i++) {
            uint256 historyIndex = indexes[start + i];
            items[i] = priceHistories[historyIndex];
        }
        return (items, total);
    }

    /**
     * @notice Gets the latest recorded price for a specific token.
     * @param tokenId The ID of the token.
     * @return The latest price, or 0 if no price history exists.
     */
    function getLatestPrice(uint256 tokenId) external view returns (uint256) {
        uint256[] storage indexes = tokenPriceHistoryIndexes[tokenId];
        if (indexes.length == 0) {
            return 0;
        }
        uint256 latestIndex = indexes[indexes.length - 1];
        return priceHistories[latestIndex].price;
    }

