     * @param interfaceId The interface identifier.
     * @return bool True if the interface is supported, false otherwise.
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        virtual
        override(ERC1155HolderUpgradeable)
        returns (bool)
    {
        return
            ERC1155HolderUpgradeable.supportsInterface(interfaceId) ||
            interfaceId == type(IAsteroidXMarketplace).interfaceId ||
            interfaceId == type(OwnableUpgradeable).interfaceId ||
            interfaceId == type(PausableUpgradeable).interfaceId ||
            super.supportsInterface(interfaceId);
    }

