    /**
     * @notice Proposes an update to the platform fee percentage.
     * @dev Can only be called by the owner. The update is subject to a timelock.
     * @param newFeePercentage The new fee percentage in basis points.
     */
    function proposeFeeUpdate(uint256 newFeePercentage) external onlyOwner {
        if (newFeePercentage > MAX_FEE_PERCENTAGE) {
            revert InvalidFeePercentage(newFeePercentage, MAX_FEE_PERCENTAGE);
        }
        pendingFeeUpdate = AsteroidXMarketplaceStructs.PendingUpdate({
            value: newFeePercentage,
            timestamp: block.timestamp
        });
        emit TimelockProposed("FEE", newFeePercentage, block.timestamp);
    }

    /**
     * @notice Executes a pending platform fee update after the timelock period.
     * @dev Can only be called by the owner.
     */
    function executeFeeUpdate() external onlyOwner {
        if (pendingFeeUpdate.timestamp == 0) revert NoPendingUpdate();
        if (block.timestamp < pendingFeeUpdate.timestamp + timelockDuration) {
            revert TimelockNotExpired(
                block.timestamp,
                pendingFeeUpdate.timestamp + timelockDuration
            );
        }
        uint256 newFee = pendingFeeUpdate.value;
        delete pendingFeeUpdate;
        platformFeePercentage = newFee;
        emit PlatformFeeUpdated(newFee);
        emit TimelockExecuted("FEE", newFee);
    }

    /**
     * @notice Proposes an update to the fee recipient address.
     * @dev Can only be called by the owner. The update is subject to a timelock.
     * @param newFeeRecipient The new address for the fee recipient.
     */
    function proposeFeeRecipientUpdate(address newFeeRecipient)
        external
        onlyOwner
    {
        if (newFeeRecipient == address(0)) revert InvalidRecipient();
        pendingRecipientUpdate = AsteroidXMarketplaceStructs.PendingUpdate({
            value: uint256(uint160(newFeeRecipient)),
            timestamp: block.timestamp
        });
        emit TimelockProposed(
            "RECIPIENT",
            uint256(uint160(newFeeRecipient)),
            block.timestamp
        );
    }

    /**
     * @notice Executes a pending fee recipient update after the timelock period.
     * @dev Can only be called by the owner.
     */
    function executeFeeRecipientUpdate() external onlyOwner {
        if (pendingRecipientUpdate.timestamp == 0) revert NoPendingUpdate();
        if (
            block.timestamp <
            pendingRecipientUpdate.timestamp + timelockDuration
        ) {
            revert TimelockNotExpired(
                block.timestamp,
                pendingRecipientUpdate.timestamp + timelockDuration
            );
        }
        address newRecipient = address(uint160(pendingRecipientUpdate.value));
        delete pendingRecipientUpdate;
        feeRecipient = newRecipient;
        emit FeeRecipientUpdated(newRecipient);
        emit TimelockExecuted("RECIPIENT", uint256(uint160(newRecipient)));
    }

    /**
     * @notice Allows a seller to cancel multiple listings in a single transaction.
     * @param listingIds An array of listing IDs to cancel.
     */
    function batchCancelListings(uint256[] calldata listingIds)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        uint256 canceledCount = 0;
        for (uint256 i = 0; i < listingIds.length; i++) {
            AsteroidXMarketplaceStructs.Listing storage listing = listings[
                listingIds[i]
            ];
            if (listing.seller != msg.sender)
                revert NotSeller(listingIds[i], msg.sender);
            if (listing.active) {
                _deactivateListing(listingIds[i]);
                marketplaceVaultContract.returnNFTToSeller(
                    address(asteroidXToken),
                    listing.tokenId,
                    listing.amount,
                    listing.seller
                );
                _recordTransaction(
                    listing.tokenId,
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING,
                    msg.sender,
                    address(0),
                    listing.amount,
                    0,
                    listing.paymentToken,
                    listingIds[i]
                );
                emit ListingCancelled(listingIds[i]);
                canceledCount++;
            }
        }
        if (canceledCount > 0) {
            emit BatchOperation(
                uint256(
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING
                ),
                canceledCount
            );
        }
    }

    /**
     * @notice Allows a buyer to cancel multiple offers in a single transaction.
     * @dev Iterates through an array of offer IDs. For each ID, it verifies that the caller is the buyer
     * and that the offer is active before proceeding with cancellation and refund.
     * @param offerIds An array of offer IDs to cancel.
     */
    function batchCancelOffers(uint256[] calldata offerIds)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        uint256 canceledCount = 0;
        for (uint256 i = 0; i < offerIds.length; i++) {
            uint256 offerId = offerIds[i];
            AsteroidXMarketplaceStructs.Offer storage offer = offers[offerId];

            // Security check: Only the buyer can cancel their own offer.
            if (offer.buyer != msg.sender) {
                revert NotBuyer(offerId, msg.sender);
            }

            // Check if the offer is active before trying to cancel.
            // This prevents reverting the whole batch if one offer is already inactive.
            if (offer.active) {
                _deactivateOffer(offerId);

                uint256 refundAmount = offer.amount * offer.pricePerToken;
                _handleOfferFundRefund(
                    offerId,
                    offer.paymentToken,
                    msg.sender, // The buyer
                    refundAmount
                );

                _recordTransaction(
                    offer.tokenId,
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_OFFER,
                    address(marketplaceVaultContract),
                    offer.buyer,
                    offer.amount,
                    offer.pricePerToken,
                    offer.paymentToken,
                    offerId
                );

                emit OfferCancelled(offerId);
                canceledCount++;
            }
        }

        if (canceledCount > 0) {
            emit BatchOperation(
                uint256(AsteroidXMarketplaceStructs.ActivityType.CANCEL_OFFER),
                canceledCount
            );
        }
    }

    /**
