    /**
     * @notice Sets or updates the configuration for a payment token (native or ERC20).
     * @dev Allows setting its support status and specific fee rate. Can only be called by the owner.
     * @param tokenAddress The address of the payment token (address(0) for native currency).
     * @param isSupported True to support/update the token, false to unsupport it.
     * @param specificFeeRateBps The fee rate in basis points (0 to MAX_FEE_PERCENTAGE). Ignored if unsupporting.
     */
    function setPaymentTokenConfig(
        address tokenAddress,
        bool isSupported,
        uint256 specificFeeRateBps
    ) external onlyOwner {
        if (isSupported) {
            if (specificFeeRateBps > MAX_FEE_PERCENTAGE)
                revert InvalidFeePercentage(
                    specificFeeRateBps,
                    MAX_FEE_PERCENTAGE
                );
            _supportedPaymentTokensSet.add(tokenAddress);
            paymentTokenFeeRates[tokenAddress] = specificFeeRateBps;
            emit PaymentTokenConfigUpdated(
                tokenAddress,
                true,
                specificFeeRateBps
            );
        } else {
            _supportedPaymentTokensSet.remove(tokenAddress);
            delete paymentTokenFeeRates[tokenAddress];
            emit PaymentTokenConfigUpdated(tokenAddress, false, 0);
        }
    }

    /**
     * @notice Retrieves all supported payment tokens and their effective fee rates.
     * @return tokens An array of currently supported payment token addresses.
     * @return effectiveFeeRatesBps An array of their corresponding fee rates in basis points.
     */
    function getAllSupportedPaymentTokensInfo()
        external
        view
        returns (address[] memory tokens, uint256[] memory effectiveFeeRatesBps)
    {
        uint256 count = _supportedPaymentTokensSet.length();
        tokens = new address[](count);
        effectiveFeeRatesBps = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            address token = _supportedPaymentTokensSet.at(i);
            tokens[i] = token;
            effectiveFeeRatesBps[i] = paymentTokenFeeRates[token];
        }
        return (tokens, effectiveFeeRatesBps);
    }

    /**
     * @notice Allows the owner to withdraw any ERC20 tokens accidentally sent to this contract.
     * @param tokenAddress The address of the ERC20 token to withdraw.
     * @param recipient The address to send the tokens to.
     */
    function emergencyWithdrawERC20(address tokenAddress, address recipient)
        external
        onlyOwner
    {
        if (tokenAddress == address(0))
            revert UnsupportedPaymentToken(tokenAddress);
        if (recipient == address(0)) revert InvalidRecipient();
        IERC20 token = IERC20(tokenAddress);
        uint256 balance = token.balanceOf(address(this));
        if (balance == 0) revert NoTokensToWithdraw();
        token.safeTransfer(recipient, balance);
        emit EmergencyWithdraw(tokenAddress, recipient, balance);
    }

    /**
     * @dev Internal function to handle payments (native or ERC20).
     * For native currency, it ensures enough ETH is sent and refunds excess.
     * For ERC20, it checks allowance and balance before transferring.
     */
    function _handlePayment(
        address paymentToken,
        address from,
        address to,
        uint256 amount,
        uint256 msgValue
    ) internal {
        if (paymentToken == address(0)) {
            if (msgValue < amount) revert InsufficientETHSent(msgValue, amount);
            if (amount > 0) {
                (bool success, ) = payable(to).call{value: amount}("");
                if (!success) revert EthTransferFailed(to);
            }
            if (msgValue > amount) {
                uint256 excessToRefund = msgValue - amount;
                (bool refundSuccess, ) = payable(from).call{
                    value: excessToRefund
                }("");
                if (!refundSuccess) revert EthRefundFailed(from);
            }
        } else {
            if (!_supportedPaymentTokensSet.contains(paymentToken))
                revert UnsupportedPaymentToken(paymentToken);
            if (msgValue != 0) revert UnexpectedETHPayment();
