            if (token.allowance(from, address(this)) < amount)
                revert InsufficientAllowance(
                    amount,
                    token.allowance(from, address(this)),
                    paymentToken
                );
            if (token.balanceOf(from) < amount)
                revert InsufficientBalance(
                    amount,
                    token.balanceOf(from),
                    paymentToken
