        address seller,
        uint256 totalAmount,
        uint256 msgValue,
        address feePaymentToken
    ) internal {
        (uint256 platformFee, uint256 sellerProceeds) = _calculateFees(
            totalAmount,
            feePaymentToken
        );
        if (paymentToken == address(0)) {
            if (msgValue < totalAmount)
                revert InsufficientETHSentForPurchase(msgValue, totalAmount);
            if (sellerProceeds > 0) {
