            revert InvalidAmount(amount, MAX_AMOUNT_PER_LISTING);
        if (pricePerToken == 0 || pricePerToken > MAX_PRICE_PER_TOKEN)
            revert InvalidPrice(pricePerToken, MAX_PRICE_PER_TOKEN);
