    {
        uint256 feeRateToUse = paymentTokenFeeRates[paymentToken];
        platformFee = (feeRateToUse > 0 && totalAmount > 0)
            ? Math.mulDiv(totalAmount, feeRateToUse, 10000)
            : 0;
        sellerProceeds = totalAmount - platformFee;
        return (platformFee, sellerProceeds);
    }

