     * @dev Internal helper to interact with the vault for withdrawing offer funds (native or ERC20).
     */
    function _handleOfferFundWithdrawal(
        uint256 offerId,
        address paymentToken,
        address seller,
        address feeRecipientAddress,
        uint256 sellerProceeds,
        uint256 platformFee
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.withdrawOfferFundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee
            );
        } else {
            marketplaceVaultContract.withdrawOfferERC20FundsToSeller(
                offerId,
                seller,
                feeRecipientAddress,
                sellerProceeds,
                platformFee,
                paymentToken
            );
        }
    }

    /**
     * @dev Internal helper to interact with the vault for refunding offer funds (native or ERC20).
     */
    function _handleOfferFundRefund(
        uint256 offerId,
        address paymentToken,
        address buyer,
        uint256 refundAmount
    ) internal {
        if (paymentToken == address(0)) {
            marketplaceVaultContract.refundOfferFundsToBuyer(
                offerId,
                buyer,
                refundAmount
            );
        } else {
            marketplaceVaultContract.refundOfferERC20FundsToBuyer(
                offerId,
                buyer,
                refundAmount,
                paymentToken
            );
        }
    }
}

