pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/token/ERC1155/utils/ERC1155HolderUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/Address.sol";

/**
 * @title AsteroidXMarketplaceVault
 * @dev A vault contract specialized for secure custody of NFT assets, ETH funds and ERC20 tokens
 */
contract AsteroidXMarketplaceVault is
    Initializable,
    ERC1155HolderUpgradeable,
    OwnableUpgradeable,
    AccessControlUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    using SafeERC20 for IERC20;
    using Address for address payable;

    bytes32 public constant MARKETPLACE_ROLE = keccak256("MARKETPLACE_ROLE");

    // Allows selective pausing of specific functions
    mapping(bytes4 => bool) public functionPaused;

    // Custom errors
    error NoEthToWithdraw();
    error InvalidRecipient();
    error FunctionIsPaused(bytes4 functionSig);
    error InvalidMarketplaceAddress();
    error InvalidTokenContract();
    error InvalidAmount();
    error InsufficientBalance();

    // Events
    event NFTTransferredToBuyer(
        address indexed tokenContract,
        uint256 indexed tokenId,
        uint256 amount,
        address indexed buyer
    );
    event NFTReturnedToSeller(
        address indexed tokenContract,
        uint256 indexed tokenId,
        uint256 amount,
        address indexed seller
    );
    event OfferFundsDeposited(uint256 indexed offerId, uint256 amount);
    event OfferFundsWithdrawnToSeller(
        uint256 indexed offerId,
        address indexed seller,
        uint256 amount
    );
    event OfferFundsWithdrawnToPlatform(
        uint256 indexed offerId,
        address indexed platformFeeRecipient,
        uint256 amount
    );
    event OfferFundsRefundedToBuyer(
        uint256 indexed offerId,
        address indexed buyer,
        uint256 amount
    );
    event EmergencyETHWithdrawal(address indexed recipient, uint256 amount);
    event EmergencyWithdrawal(
        address indexed tokenContract,
        uint256 indexed tokenId,
        uint256 amount,
        address indexed recipient
    );
    event MarketplaceContractUpdated(address indexed newMarketplaceContract);
    event FunctionPauseChanged(bytes4 indexed functionSig, bool isPaused);

    /**
     * @dev Initialization function, sets up the basic contract state
     */
    function initialize() public initializer {
        __ERC1155Holder_init();
        __Ownable_init(msg.sender);
        __AccessControl_init();
        __Pausable_init();
        __ReentrancyGuard_init();

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /**
     * @dev Sets the marketplace contract address. Can only be called by the owner.
     * @param _marketplaceContract The address of the marketplace contract
     */
    function setMarketplaceContract(address _marketplaceContract)
        external
        onlyOwner
    {
        if (_marketplaceContract == address(0))
            revert InvalidMarketplaceAddress();

        _grantRole(MARKETPLACE_ROLE, _marketplaceContract);
        emit MarketplaceContractUpdated(_marketplaceContract);
    }

    // Modifier that restricts calls when a specific function is paused
    modifier whenFunctionNotPaused() {
        if (functionPaused[msg.sig]) revert FunctionIsPaused(msg.sig);
        _;
    }

    /**
     * @dev Pause a specific function
     * @param functionSig Function signature
     * @param isPaused Whether to pause or unpause
     */
    function setFunctionPaused(bytes4 functionSig, bool isPaused)
        external
        onlyOwner
    {
        functionPaused[functionSig] = isPaused;
        emit FunctionPauseChanged(functionSig, isPaused);
    }

    /**
     * @dev Pause the contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause the contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Transfer NFT to buyer (only callable by Marketplace contract)
     * @param tokenContract NFT contract address
     * @param tokenId NFT ID
     * @param amount Amount
     * @param buyer Buyer address
     */
    function transferNFTToBuyer(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (buyer == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            buyer,
            tokenId,
            amount,
            ""
        );
        emit NFTTransferredToBuyer(tokenContract, tokenId, amount, buyer);
    }

    /**
     * @dev Return NFT to seller (only callable by Marketplace contract)
     * @param tokenContract NFT contract address
     * @param tokenId NFT ID
     * @param amount Amount
     * @param seller Seller address
     */
    function returnNFTToSeller(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address seller
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (seller == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            seller,
            tokenId,
            amount,
            ""
        );
        emit NFTReturnedToSeller(tokenContract, tokenId, amount, seller);
    }

    /**
     * @dev Receive offer funds in ETH (only callable by Marketplace contract)
     * @param offerId Offer ID (for tracking)
     */
    function depositOfferFunds(uint256 offerId)
        external
        payable
        onlyRole(MARKETPLACE_ROLE)
        whenNotPaused
        whenFunctionNotPaused
    {
        emit OfferFundsDeposited(offerId, msg.value);
    }

    /**
     * @dev Process ERC20 payment for offer (deposit ERC20 tokens to vault)
     * @param offerId Offer ID for tracking
     * @param token ERC20 token address
     * @param amount Amount to deposit
     * @param buyer Buyer address
     */
    function depositOfferERC20Funds(
        uint256 offerId,
        address token,
        uint256 amount,
        address buyer
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (token == address(0)) revert InvalidTokenContract();
        if (amount == 0) revert InvalidAmount();

        // Transfer ERC20 tokens from buyer to this contract
        IERC20(token).safeTransferFrom(buyer, address(this), amount);

        emit OfferFundsDeposited(offerId, amount);
    }

    /**
     * @dev Transfer offer ETH funds to seller and platform (only callable by Marketplace contract)
     * @param offerId Offer ID (for tracking)
     * @param seller Seller address
     * @param platformFeeRecipient Platform fee recipient address
     * @param sellerProceeds Seller proceeds amount
     * @param platformFee Platform fee amount
     */
    function withdrawOfferFundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        uint256 totalAmount = sellerProceeds + platformFee;
        if (totalAmount > address(this).balance) revert InsufficientBalance();

        // First transfer to seller
        payable(seller).sendValue(sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            payable(platformFeeRecipient).sendValue(platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

    /**
     * @dev Transfer offer ERC20 funds to seller and platform
     * @param offerId Offer ID for tracking
     * @param seller Seller address
     * @param platformFeeRecipient Platform fee recipient address
     * @param sellerProceeds Seller proceeds amount
     * @param platformFee Platform fee amount
     * @param token ERC20 token address
     */
    function withdrawOfferERC20FundsToSeller(
        uint256 offerId,
        address seller,
        address platformFeeRecipient,
        uint256 sellerProceeds,
        uint256 platformFee,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (seller == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (sellerProceeds == 0) revert InvalidAmount();
        if (platformFee > 0 && platformFeeRecipient == address(0))
            revert InvalidRecipient();

        // Get the ERC20 token contract
        IERC20 erc20Token = IERC20(token);

        // First transfer to seller
        erc20Token.safeTransfer(seller, sellerProceeds);
        emit OfferFundsWithdrawnToSeller(offerId, seller, sellerProceeds);

        // Then transfer platform fee (if platform fee is greater than 0)
        if (platformFee > 0) {
            erc20Token.safeTransfer(platformFeeRecipient, platformFee);
            emit OfferFundsWithdrawnToPlatform(
                offerId,
                platformFeeRecipient,
                platformFee
            );
        }
    }

    /**
     * @dev Refund offer ETH funds to buyer (only callable by Marketplace contract)
     * @param offerId Offer ID (for tracking)
     * @param buyer Buyer address
     * @param refundAmount Refund amount
     */
    function refundOfferFundsToBuyer(
        uint256 offerId,
        address buyer,
        uint256 refundAmount
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (buyer == address(0)) revert InvalidRecipient();
        if (refundAmount == 0) revert InvalidAmount();
        if (refundAmount > address(this).balance) revert InsufficientBalance();

        payable(buyer).sendValue(refundAmount);
        emit OfferFundsRefundedToBuyer(offerId, buyer, refundAmount);
    }

    /**
     * @dev Refund offer ERC20 funds to buyer
     * @param offerId Offer ID (for tracking)
     * @param buyer Buyer address
     * @param refundAmount Refund amount
     * @param token ERC20 token address
     */
    function refundOfferERC20FundsToBuyer(
        uint256 offerId,
        address buyer,
        uint256 refundAmount,
        address token
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (buyer == address(0)) revert InvalidRecipient();
        if (token == address(0)) revert InvalidTokenContract();
        if (refundAmount == 0) revert InvalidAmount();

        // Transfer ERC20 tokens back to buyer
        IERC20(token).safeTransfer(buyer, refundAmount);

        emit OfferFundsRefundedToBuyer(offerId, buyer, refundAmount);
    }

    /**
     * @dev Allow Owner to withdraw ETH funds from the contract in emergency (for exceptional cases)
     */
    function emergencyWithdrawETH() external onlyOwner {
        uint256 balance = address(this).balance;
        if (balance == 0) revert NoEthToWithdraw();

        payable(owner()).sendValue(balance);
        emit EmergencyETHWithdrawal(owner(), balance);
    }

    /**
     * @dev Allow Owner to withdraw ERC20 tokens from the contract in emergency
     * @param token ERC20 token address
     * @param recipient Recipient address
     * @param amount Amount to withdraw
     */
    function emergencyWithdrawERC20(
        address token,
        address recipient,
        uint256 amount
    ) external onlyOwner {
        if (token == address(0)) revert InvalidTokenContract();
        if (recipient == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC20(token).safeTransfer(recipient, amount);
        emit EmergencyETHWithdrawal(recipient, amount);
    }

    /**
     * @dev Allow Owner to withdraw ERC1155 Tokens from the contract in emergency (for exceptional cases)
     * @param tokenContract NFT contract address
     * @param tokenId NFT ID
     * @param amount Amount
     * @param recipient Recipient address
     */
    function emergencyWithdrawERC1155(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address recipient
    ) external onlyOwner {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (recipient == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            recipient,
            tokenId,
            amount,
            ""
        );
        emit EmergencyWithdrawal(tokenContract, tokenId, amount, recipient);
    }

    /**
     * @dev Override for solving the diamond inheritance problem
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        virtual
        override(ERC1155HolderUpgradeable, AccessControlUpgradeable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    /**
     * @dev Reserved storage space for future upgrades
     */
    uint256[50] private __gap;
}

