/**
 * @title AsteroidXMarketplace Structs and Enums
 * @dev Contains common structures and enumerations used in the AsteroidXMarketplace contract
 */
library AsteroidXMarketplaceStructs {
    // Listing structure
    struct Listing {
        uint256 listingId;
        address seller;
        uint256 tokenId;
        uint256 amount;
        uint256 pricePerToken;
        uint256 expirationTime;
        bool active;
        uint256 timestamp;
        address paymentToken;
    }

    // Offer structure
    struct Offer {
        uint256 offerId;
        address buyer;
        uint256 tokenId;
        uint256 amount;
        uint256 pricePerToken;
        uint256 expirationTime;
        bool active;
        uint256 timestamp;
        address paymentToken;
    }

    // Activity types
    enum ActivityType {
        LISTING,
        SALE,
        TRANSFER,
        CANCEL_LISTING,
        MAKE_OFFER,
        CANCEL_OFFER,
        ACCEPT_OFFER
    }

    // Activity structure
    struct Activity {
        ActivityType activityType;
        address from;
        address to;
        uint256 tokenId;
        uint256 amount;
        uint256 price;
        uint256 timestamp;
        address paymentToken;
    }

    // PriceRecord structure
    struct PriceRecord {
        uint256 listingId;
        uint256 tokenId;
        uint256 price;
        uint256 amount;
        uint256 totalValue;
        uint256 timestamp;
        address seller;
        address buyer;
        address paymentToken;
    }

    // PendingUpdate structure
    struct PendingUpdate {
        uint256 value;
        uint256 timestamp;
    }
}

