// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../AsteroidXMarketplaceStructs.sol";
import "../AsteroidXMarketplaceErrors.sol";

interface IAsteroidXMarketplace {
    // Listing Functions
    function createListing(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) external;

    function purchaseListing(
        uint256 listingId,
        uint256 amount
    ) external payable;

    function cancelListing(uint256 listingId) external;

    // Offer Functions
    function makeOffer(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerToken,
        uint256 expirationTime,
        address paymentToken
    ) external payable;

    function cancelOffer(uint256 offerId) external;

    function acceptOffer(uint256 offerId) external;

    // Query Functions
    function getActiveListing(
        uint256 listingId
    ) external view returns (AsteroidXMarketplaceStructs.Listing memory);

    function getActiveListingsPaginated(
        uint256 tokenId,
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (AsteroidXMarketplaceStructs.Listing[] memory, uint256);

    function getActiveOffersPaginated(
        uint256 tokenId,
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (AsteroidXMarketplaceStructs.Offer[] memory, uint256);

    function getActiveOffersByBuyerPaginated(
        address buyer,
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (AsteroidXMarketplaceStructs.Offer[] memory, uint256);

    function getLatestPrice(uint256 tokenId) external view returns (uint256);

    function getTokenActivities(
        uint256 tokenId
    ) external view returns (AsteroidXMarketplaceStructs.Activity[] memory);

    function getTokenActivitiesPaginated(
        uint256 tokenId,
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (
            AsteroidXMarketplaceStructs.Activity[] memory items,
            uint256 total
        );
}

